api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.mgc-page {
  max-width: 1400px;
  margin: 0 auto;
  padding: 30px;
  background: #f7f9fc;
  min-height: 100vh;
  font-family: Arial, sans-serif;
  color: #10204a;
}


/* =========================
   HEADER
========================= */

.mgc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 22px;
}

.mgc-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
  color: #10204a;
}

.mgc-header p {
  margin: 0;
  font-size: 13px;
  color: #7b8498;
}

.mgc-back {
  text-decoration: none !important;
  color: #2563d9 !important;
  font-size: 13px;
  font-weight: 500;
}


/* =========================
   SUMMARY CARDS
========================= */

.mgc-summary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  margin-bottom: 22px;
}

.mgc-summary > div {
  background: #ffffff;
  border: 1px solid #e4e8ef;
  border-radius: 12px;
  padding: 18px 20px;
  box-shadow: 0 3px 10px rgba(20, 40, 90, .04);
}

.mgc-summary span {
  display: block;
  font-size: 11px;
  color: #7c859a;
  margin-bottom: 7px;
}

.mgc-summary strong {
  display: block;
  font-size: 18px;
  color: #12204b;
}


/* =========================
   MAIN CARD
========================= */

.mgc-card {
  background: #ffffff;
  border: 1px solid #e3e7ee;
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 3px 12px rgba(25, 40, 80, .05);
}

.mgc-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.mgc-card-header h3 {
  margin: 0 0 4px;
  font-size: 18px;
  font-weight: 700;
  color: #10204a;
}

.mgc-card-header p {
  margin: 0;
  font-size: 11px;
  color: #81899d;
}


/* =========================
   SEARCH
========================= */

.mgc-search {
  width: 280px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: #ffffff;
  border: 1px solid #dfe4ec;
  border-radius: 9px;
  padding: 9px 11px;
}

.mgc-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-size: 12px;
  color: #26314c;
}

.mgc-search input::placeholder {
  color: #9aa1b2;
}


/* =========================
   TABLE
========================= */

.mgc-table-wrap {
  width: 100%;
  overflow-x: auto;
}

.mgc-table {
  width: 100%;
  border-collapse: collapse;
}

.mgc-table th {
  background: #f5f7fa;
  color: #323c58;
  font-size: 11px;
  font-weight: 700;
  text-align: left;
  padding: 12px 10px;
  border-bottom: 1px solid #e8ecf2;
  white-space: nowrap;
}

.mgc-table td {
  padding: 13px 10px;
  border-bottom: 1px solid #edf0f4;
  font-size: 12px;
  color: #283451;
  white-space: nowrap;
}

.mgc-table tbody tr:hover {
  background: #fafbfe;
}

.mgc-table tr:last-child td {
  border-bottom: none;
}


/* =========================
   CASE LINK
========================= */

.case-link {
  color: #1769df !important;
  text-decoration: none !important;
  font-weight: 700;
}

.case-link:hover {
  text-decoration: underline !important;
}


/* =========================
   PRIORITY PILLS
========================= */

.priority-pill {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 14px;
  font-size: 10px;
  font-weight: 600;
}

.priority-high {
  background: #fde8e7;
  color: #d94339;
}

.priority-medium {
  background: #fff1d8;
  color: #d17a00;
}

.priority-low {
  background: #e5f6ec;
  color: #16875a;
}


/* =========================
   STATUS PILLS
========================= */

.status-pill {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 14px;
  font-size: 10px;
  font-weight: 600;
}

.status-open {
  background: #fff0dc;
  color: #ca7400;
}

.status-progress {
  background: #e6efff;
  color: #2d70d7;
}

.status-resolved {
  background: #e3f6ec;
  color: #16875a;
}

.status-closed {
  background: #edf0f4;
  color: #60697c;
}


/* =========================
   OTHER TEXT
========================= */

.unassigned {
  color: #9da4b5;
  font-style: italic;
}

.empty-row {
  text-align: center !important;
  color: #929bad !important;
  padding: 28px !important;
}


/* =========================
   UNAUTHORIZED
========================= */

.unauthorized-box {
  margin-top: 20px;
  padding: 16px 18px;
  background: #fff3e5;
  color: #a15c00;
  border: 1px solid #f1d4ad;
  border-radius: 10px;
  font-size: 13px;
}


.status-awaiting {
  background: #fff4d6;
  color: #a35d00;
}


/* =========================
   RESPONSIVE
========================= */

@media (max-width: 900px) {

  .mgc-page {
    padding: 20px;
  }

  .mgc-summary {
    grid-template-columns: 1fr;
  }

  .mgc-card-header {
    display: block;
  }

  .mgc-search {
    width: 100%;
    margin-top: 15px;
  }
}

@media (max-width: 600px) {

  .mgc-header {
    display: block;
  }

  .mgc-back {
    display: inline-block;
    margin-top: 14px;
  }
}

sp_widget.script:
(function() {

    // -------------------------------
    // LOGGED-IN USER
    // -------------------------------

    data.userName = gs.getUserDisplayName();
    data.userId = gs.getUserID();

    data.initials = "";

    var parts = data.userName.split(" ");

    for (var i = 0; i < parts.length && i < 2; i++) {

        if (parts[i]) {

            data.initials +=
                parts[i]
                    .charAt(0)
                    .toUpperCase();
        }
    }


    // -------------------------------
    // HR AGENT GROUPS
    // -------------------------------

    data.isHRAgent = false;

    data.agentGroupNames = [];
    data.agentGroupIds = [];


    var allowedGroups = [

        'HR Payroll',

        'HR Benefits',

        'HR Employee Relations',

        'HR General',

        'HR Leave Administration'

    ];


    var memberGR =
        new GlideRecord(
            'sys_user_grmember'
        );


    memberGR.addQuery(
        'user',
        data.userId
    );


    memberGR.addQuery(
        'group.name',
        'IN',
        allowedGroups.join(',')
    );


    memberGR.query();


    while (memberGR.next()) {

        data.isHRAgent = true;


        data.agentGroupNames.push(

            memberGR.getDisplayValue(
                'group'
            )

        );


        data.agentGroupIds.push(

            memberGR.getValue(
                'group'
            )

        );
    }


    // -------------------------------
    // ROLE LABEL
    // -------------------------------

    if (
        data.agentGroupNames.length == 1
    ) {

        data.roleLabel =
            data.agentGroupNames[0] +
            " Agent";

    }

    else if (
        data.agentGroupNames.length > 1
    ) {

        data.roleLabel =
            "HR Agent";

    }

    else {

        data.roleLabel =
            "Unauthorized User";
    }


    // -------------------------------
    // CASE ARRAY
    // -------------------------------

    data.cases = [];


    // -------------------------------
    // LOAD AGENT CASES
    // -------------------------------

    if (
        data.isHRAgent &&
        data.agentGroupIds.length > 0
    ) {

        var caseGR =
            new GlideRecord(
                'x_snc_unified_hr_0_hr_case'
            );


        var groupCondition =
            caseGR.addQuery(
                'assignment_group',
                'IN',
                data.agentGroupIds.join(',')
            );


        groupCondition.addOrCondition(
            'assigned_to',
            data.userId
        );


        caseGR.orderByDesc(
            'sys_created_on'
        );


        caseGR.query();


        while (caseGR.next()) {


            // -------------------------------
            // STATUS VALUE + FRIENDLY LABEL
            // -------------------------------

            var statusValue =
                caseGR.getValue(
                    'status'
                );


            var statusLabel =
                caseGR.getDisplayValue(
                    'status'
                );


            if (
                statusValue ==
                'awaiting_employee_confirmation'
            ) {

                statusLabel =
                    'Awaiting Employee Confirmation';
            }


            // -------------------------------
            // CREATED DATE
            // -------------------------------

            var createdOn =
                caseGR.getDisplayValue(
                    'created_on'
                );


            if (!createdOn) {

                createdOn =
                    caseGR.getDisplayValue(
                        'sys_created_on'
                    );
            }


            // -------------------------------
            // PUSH CASE DATA
            // -------------------------------

            data.cases.push({

                sys_id:
                    caseGR.getUniqueValue(),


                number:
                    caseGR.getDisplayValue(
                        'number'
                    ),


                requested_by:
                    caseGR.getDisplayValue(
                        'request_by'
                    ),


                category:
                    caseGR.getDisplayValue(
                        'category'
                    ),


                priority:
                    caseGR.getDisplayValue(
                        'priority'
                    ),


                assignment_group:
                    caseGR.getDisplayValue(
                        'assignment_group'
                    ),


                assigned_to:
                    caseGR.getDisplayValue(
                        'assigned_to'
                    ),


                status:
                    statusLabel,


                status_value:
                    statusValue,


                created_on:
                    createdOn

            });
        }
    }


    // -------------------------------
    // TOTAL CASE COUNT
    // -------------------------------

    data.totalCases =
        data.cases.length;

})();
